<?php
namespace Database\Seeders;
use Illuminate\Database\Seeder;
use Illuminate\Support\Facades\DB;
/** Mengisi contoh jasa ekosistem untuk setiap area terdampak. */
class JasaEkosistemSeeder extends Seeder { public function run(): void { $areas=\Illuminate\Support\Facades\DB::table('area_terdampak')->pluck('id_area'); foreach($areas as $id){ \Illuminate\Support\Facades\DB::table('provisioning_service')->updateOrInsert(['id_area'=>$id,'nama_objek'=>'Hasil perikanan lokal'],['produktivitas'=>1.2500,'harga_pasar'=>35000,'luas_pemanfaatan'=>5,'satuan_luas'=>'Hektar','referensi'=>'Survei lapangan 2026','nilai'=>218750]); \Illuminate\Support\Facades\DB::table('regulating_service')->updateOrInsert(['id_area'=>$id,'jenis_regulating'=>'Perlindungan pesisir'],['indikator'=>'Luas tutupan','satuan'=>'Hektar','nilai_indikator'=>10,'referensi'=>'Peta tutupan lahan','nilai'=>150000000]); \Illuminate\Support\Facades\DB::table('supporting_service')->updateOrInsert(['id_area'=>$id,'fungsi_pendukung'=>'Habitat dan siklus nutrien'],['deskripsi'=>'Menopang keanekaragaman hayati.','referensi'=>'Kajian ekologi 2025','nilai'=>75000000]); \Illuminate\Support\Facades\DB::table('cultural_service')->updateOrInsert(['id_area'=>$id,'nama_aktivitas'=>'Wisata edukasi ekosistem'],['jumlah_pengunjung'=>1200,'biaya_perjalanan'=>150000,'frekuensi'=>1,'referensi'=>'Survei pengunjung 2026','nilai'=>180000000]); } } }
